import SwiftUI

// MARK: - Sprite data (generated by tools/make_slime.py into sprites.json)

struct ItemSprite: Decodable {
    let palette: [String: UInt32]
    let rows: [String]

    func color(_ key: Character) -> Color? {
        palette[String(key)].map { Color(hex: $0) }
    }
}

struct AccessorySprite: Decodable {
    let kind: String
    let palette: [String: UInt32]
    let rows: [String]
    let island: UInt32
}

enum SlimeSprites {
    struct Bundle: Decodable {
        let width: Int
        let height: Int
        let frames: [String: [[String]]]
        let anchors: [String: [[Int]]]
        let accessories: [String: AccessorySprite]
        let items: [String: ItemSprite]
        let emoteIcons: [String: [String]]
        let emoteReels: [String: [String]]

        static let empty = Bundle(width: 24, height: 20, frames: [:], anchors: [:], accessories: [:],
                                  items: [:], emoteIcons: [:], emoteReels: [:])
    }

    /// Loaded once, the first time any sprite is drawn.
    static let data: Bundle = {
        guard let url = Foundation.Bundle.main.url(forResource: "sprites", withExtension: "json"),
              let raw = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode(Bundle.self, from: raw) else { return .empty }
        return decoded
    }()

    static var width: Int { data.width }
    static var height: Int { data.height }
    static var items: [String: ItemSprite] { data.items }
    static var emoteIcons: [String: [String]] { data.emoteIcons }
    static var emoteReels: [String: [String]] { data.emoteReels }

    static let blank = Array(repeating: String(repeating: ".", count: 24), count: 20)

    static func frames(_ stage: Stage, _ anim: SpriteAnim) -> [[String]] {
        data.frames["\(stage.rawValue).\(anim.rawValue)"] ?? data.frames["young.idle"] ?? [blank]
    }

    /// Per frame: [head top, eye row, neck row, look offset].
    static func anchors(_ stage: Stage, _ anim: SpriteAnim) -> [[Int]] {
        data.anchors["\(stage.rawValue).\(anim.rawValue)"] ?? []
    }
}

/// The animations, the same in app and island.
enum SpriteAnim: String, CaseIterable {
    case idle, sad, sleep, eat, play, love, bath, melt, zap, confused, wave
    case celebrate, stretch, sulk, hide, curious, blush

    init(_ mood: Mood) {
        self = SpriteAnim(rawValue: mood.rawValue) ?? .idle
    }

    init?(_ reaction: Reaction) {
        guard reaction != .none else { return nil }
        self.init(rawValue: reaction.rawValue)
    }

    /// The single frame that best shows this animation when it can't move.
    /// Idle changes pose with every update so the island doesn't look frozen.
    func posterIndex(at date: Date) -> Int {
        switch self {
        case .idle: [0, 1, 3, 5][Calendar.current.component(.minute, from: date) % 4]
        case .play, .celebrate: 1
        default: 0
        }
    }
}

// MARK: - Shapes

/// All pixels of one character in a grid of strings.
struct PixelGridShape: Shape {
    let rows: [String]
    let code: Character
    var cols: Int = 24
    var count: Int = 20
    /// Aligns the grid to the bottom (slimes) or centre (items).
    var bottom = true

    func path(in rect: CGRect) -> Path {
        let c = CGFloat(cols), r = CGFloat(count)
        let px = min(rect.width / c, rect.height / r)
        let ox = rect.minX + (rect.width - px * c) / 2
        let oy = bottom ? rect.maxY - px * r : rect.minY + (rect.height - px * r) / 2
        var path = Path()
        for (y, row) in rows.enumerated() {
            let chars = Array(row)
            var x = 0
            while x < chars.count {
                guard chars[x] == code else { x += 1; continue }
                let start = x
                while x < chars.count, chars[x] == code { x += 1 }
                // A hair of overlap hides seams between neighbouring pixels.
                path.addRect(CGRect(x: ox + CGFloat(start) * px, y: oy + CGFloat(y) * px,
                                    width: CGFloat(x - start) * px + 0.4, height: px + 0.4))
            }
        }
        return path
    }
}

/// A one-colour pixel icon ('#' = filled).
struct IconShape: Shape {
    let rows: [String]

    func path(in rect: CGRect) -> Path {
        PixelGridShape(rows: rows, code: "#", cols: rows.first?.count ?? 1, count: max(1, rows.count), bottom: false)
            .path(in: rect)
    }
}

// MARK: - Slime

/// One frame of the slime, with accessories, drawn crisply at any size.
struct PixelSlime: View {
    let frame: [String]
    let skin: Skin
    var accessories = Accessories()
    var stage: Stage = .young
    var anchor: [Int]? = nil
    var effects = true

    var body: some View {
        ZStack {
            ForEach(SpriteLayer.allCases, id: \.self) { layer in
                if effects || (layer != .warm && layer != .cool) {
                    PixelGridShape(rows: frame, code: layer.code).fill(skin.color(for: layer))
                }
            }
            ForEach(accessoryLayers, id: \.id) { layer in
                PixelGridShape(rows: layer.rows, code: layer.code).fill(layer.color)
            }
        }
        .aspectRatio(CGFloat(SlimeSprites.width) / CGFloat(SlimeSprites.height), contentMode: .fit)
        .accessibilityHidden(true)
    }

    private struct AccLayer {
        let id: String
        let rows: [String]
        let code: Character
        let color: Color
    }

    private var accessoryLayers: [AccLayer] {
        guard let anchor, anchor.count >= 4 else { return [] }
        var out: [AccLayer] = []
        for item in [accessories.scarf, accessories.glasses, accessories.hat].compactMap({ $0 }) {
            guard let sprite = SlimeSprites.data.accessories[item] else { continue }
            let grid = AccessoryPlacer.place(sprite, on: frame, anchor: anchor)
            for (key, hex) in sprite.palette {
                guard let ch = key.first else { continue }
                out.append(AccLayer(id: "\(item).\(key)", rows: grid, code: ch, color: Color(hex: hex)))
            }
        }
        return out
    }
}

/// Puts an accessory onto a frame, the same way the generator does for the
/// island fonts (tools/make_slime.py, place_accessory).
enum AccessoryPlacer {
    static func place(_ sprite: AccessorySprite, on frame: [String], anchor: [Int]) -> [String] {
        let w = SlimeSprites.width, h = SlimeSprites.height
        var grid = Array(repeating: Array(repeating: Character("."), count: w), count: h)
        func put(_ x: Int, _ y: Int, _ c: Character) {
            if x >= 0, x < w, y >= 0, y < h { grid[y][x] = c }
        }
        let cx = (w - 1) / 2 + 1   // round(11.5) in Python rounds to 12
        let top = anchor[0], ey = anchor[1], neck = anchor[2], look = anchor[3]
        switch sprite.kind {
        case "hat":
            let x0 = cx - (sprite.rows.first?.count ?? 0) / 2
            let y0 = top - sprite.rows.count + 1
            for (dy, row) in sprite.rows.enumerated() {
                for (dx, ch) in row.enumerated() where ch != "." { put(x0 + dx, y0 + dy, ch) }
            }
        case "glasses":
            let x0 = cx - (sprite.rows.first?.count ?? 0) / 2 + look
            for (dy, row) in sprite.rows.enumerated() {
                for (dx, ch) in row.enumerated() where ch != "." { put(x0 + dx, ey - 1 + dy, ch) }
            }
        case "scarf":
            func span(_ y: Int) -> (Int, Int)? {
                guard y >= 0, y < frame.count else { return nil }
                let chars = Array(frame[y])
                let xs = chars.indices.filter { "bsk".contains(chars[$0]) }
                guard let a = xs.first, let b = xs.last else { return nil }
                return (a, b)
            }
            for (i, y) in [neck, neck + 1].enumerated() {
                guard let (a, b) = span(y) else { continue }
                for x in a...b { put(x, y, (x + i) % 3 == 0 ? "b" : "a") }
            }
            if let (a, _) = span(neck) {
                put(a + 3, neck + 2, "a")
                put(a + 3, neck + 3, "b")
            }
        default:
            break
        }
        return grid.map { String($0) }
    }
}

// MARK: - Items

/// A small multi-colour sprite (food, coin, furniture …) from the sprite data.
struct PixelItem: View {
    let name: String

    var body: some View {
        if let sprite = SlimeSprites.items[name] {
            let cols = sprite.rows.first?.count ?? 1
            ZStack {
                ForEach(sprite.palette.keys.sorted(), id: \.self) { key in
                    if let ch = key.first {
                        PixelGridShape(rows: sprite.rows, code: ch, cols: cols, count: sprite.rows.count, bottom: false)
                            .fill(Color(hex: sprite.palette[key] ?? 0))
                    }
                }
            }
            .aspectRatio(CGFloat(cols) / CGFloat(max(1, sprite.rows.count)), contentMode: .fit)
            .accessibilityHidden(true)
        }
    }
}

extension Food {
    var spriteName: String { rawValue }
}
